func isRepositoryGitPath(path string) bool {
	// Clean the path to resolve ".." and "." components, preventing directory traversal.
	cleanedPath := filepath.Clean(path)

	// Normalize path to use forward slashes and lowercase for consistent, case-insensitive checks.
	lowerPath := strings.ToLower(filepath.ToSlash(cleanedPath))

	// A repository path should not contain a directory named ".git" or ".git.",
	// which are reserved for the internal data of a working copy.
	for _, part := range strings.Split(lowerPath, "/") {
		if part == ".git" || part == ".git." {
			return false
		}
	}

	// A valid repository path is a directory ending with ".git".
	// The check for ".git." is a defense for Windows where "path." can be treated as "path".
	return strings.HasSuffix(lowerPath, ".git") || strings.HasSuffix(lowerPath, ".git.")
}

