func isAllowedToRun(uid uint32, args []string) bool {
	// A command can run if any of the following are true:
	//	* It runs as root
	//	* It's contained in nonRootAllowed
	//	* It's a "pure" help request
	// note: commands still need valid context and snaps can only access own config.
	if uid == 0 {
		return true
	}

	if len(args) == 0 {
		return true // `snapctl` with no arguments shows help, allow for anyone.
	}

	// For unprivileged users, allow simple help requests like:
	// snapctl -h
	// snapctl <cmd> --help
	// but disallow using a help flag to bypass checks for privileged commands:
	// snapctl <privileged-cmd> <arg> --help
	hasHelp := strutil.ListContains(args, "-h") || strutil.ListContains(args, "--help")
	if hasHelp {
		// consider `snapctl set system.foo=bar --help`
		// args[0] is "set", which is a privileged command.
		// args[1] is "system.foo=bar", an argument to set
		// args[2] is "--help"
		//
		// this should be disallowed, as it's not a pure help request.
		// a pure help request has at most one non-flag argument,
		// which is the command name.
		nonFlagArgs := 0
		for _, arg := range args {
			if !strings.HasPrefix(arg, "-") {
				nonFlagArgs++
			}
		}
		// `snapctl cmd --help` has nonFlagArgs == 1 ("cmd")
		// `snapctl --help` has nonFlagArgs == 0
		// `snapctl cmd arg --help` has nonFlagArgs == 2 ("cmd", "arg")
		if nonFlagArgs <= 1 {
			return true
		}
	}

	// last, check if the command is in the explicit allow-list
	return strutil.ListContains(nonRootAllowed, args[0])
}

