func isAllowedToRun(uid uint32, args []string) bool {
	// A command can run if any of the following are true:
	//	* It runs as root
	//	* It's contained in nonRootAllowed
	//	* It's used with the -h or --help flags
	// note: commands still need valid context and snaps can only access own config.
	if uid == 0 {
		return true
	}

	if len(args) == 0 {
		return true // `snapctl` with no arguments shows help, allow for anyone.
	}

	// check if any of the args is a help flag
	// we cannot use flag.Parse() here as this is too early
	// and would interfere with the actual command parsing
	var hasHelpFlag bool
	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			hasHelpFlag = true
			break
		}
	}

	// a command is allowed if it is in the list of allowed command for
	// non-root users or if it is a request for help
	return strutil.ListContains(nonRootAllowed, args[0]) || hasHelpFlag
}

