func (t *TemplateSigner) Verify(data []byte, tmpl SignableTemplate) (bool, error) {
	// a template can have only one digest
	digestDataArr := ReDigest.FindAll(data, -1)
	if len(digestDataArr) > 1 {
		return false, errors.New("multiple digests found")
	}
	if len(digestDataArr) == 0 {
		return false, errors.New("digest not found")
	}
	digestData := digestDataArr[0]

	digestData = bytes.TrimSpace(bytes.TrimPrefix(digestData, []byte(SignaturePattern)))
	// remove fragment from digest as it is used for re-signing purposes only
	digestString := strings.TrimSuffix(string(digestData), ":"+t.GetUserFragment())
	digest, err := hex.DecodeString(digestString)
	if err != nil {
		return false, err
	}

	// before calculating signature normalize file line endings
	// this is to avoid issues with git changing line endings
	// to \r\n on windows
	normalizedData := bytes.ReplaceAll(RemoveSignatureFromData(data), []byte("\r\n"), []byte("\n"))
	buff := bytes.NewBuffer(normalizedData)
	// if file has any imports process them
	for _, file := range tmpl.GetFileImports() {
		bin, err := os.ReadFile(file)
		if err != nil {
			return false, err
		}
		buff.WriteRune('\n')
		// also normalize imported files
		normalizedBin := bytes.ReplaceAll(bin, []byte("\r\n"), []byte("\n"))
		buff.Write(normalizedBin)
	}

	return t.verify(buff.Bytes(), digest)
}

