			linkTarget := filepath.Join(linkDir, header.Linkname)

			// We must resolve the link target to an absolute path, cleaning it up
			// to prevent any ../ shenanigans.
			linkTarget, err = filepath.Abs(linkTarget)
			if err != nil {
				return fmt.Errorf("invalid symlink %q: %s", header.Name, err)
			}
			linkTarget = filepath.Clean(linkTarget)

			// The resolved link target must be within the destination directory.
			if !strings.HasPrefix(linkTarget, dst+string(os.PathSeparator)) && linkTarget != dst {
				return fmt.Errorf("invalid symlink (%q -> %q) has external target",
