func Unpack(r io.Reader, dst string) error {
	// Decompress as we read.
	uncompressed, err := gzip.NewReader(r)
	if err != nil {
		return fmt.Errorf("Failed to uncompress slug: %v", err)
	}

	// Untar as we read.
	untar := tar.NewReader(uncompressed)

	// Clean up the destination
	dst, err = filepath.Abs(dst)
	if err != nil {
		return err
	}
	dst = filepath.Clean(dst)

	// Keep track of directories and symlinks we have created.
	dirs := make(map[string]struct{})
	symlinks := make(map[string]struct{})

	// Unpackage all the contents into the directory.
	for {
		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("Failed to untar slug: %v", err)
		}

		// The tar header name is supposed to be a relative path.
		if filepath.IsAbs(header.Name) {
			return fmt.Errorf("invalid path %q is absolute", header.Name)
		}

		// The path is joining the destination directory with the name from the
		// tar header.
		path := filepath.Join(dst, header.Name)
		if !strings.HasPrefix(path, dst+string(os.PathSeparator)) && path != dst {
			return fmt.Errorf("invalid path %q is outside of destination", header.Name)
		}

		// Check if any part of the path is a symlink that we have created. If
		// it is, then we can't extract this file.
		//
		// We start with the directory of the path and walk up.
		p := filepath.Dir(path)
		for {
			// If we've hit the root, we're done.
			if !strings.HasPrefix(p, dst+string(os.PathSeparator)) && p != dst {
				break
			}

			// If this path is a symlink, then we can't extract.
			if _, ok := symlinks[p]; ok {
				return fmt.Errorf("Cannot extract %q through symlink", header.Name)
			}

			// Go to the parent
			p = filepath.Dir(p)
		}

		// Make the directories to the path.
		dir := filepath.Dir(path)
		if _, ok := dirs[dir]; !ok {
			if err := os.MkdirAll(dir, 0755); err != nil {
				return fmt.Errorf("Failed to create directory %q: %v", dir, err)
			}
			dirs[dir] = struct{}{}
		}

		// Handle the various types of files.
		switch header.Typeflag {
		case tar.TypeDir:
			// This is a directory. We already created it above, so we can just
			// record it and continue.
			dirs[path] = struct{}{}

		case tar.TypeSymlink:
			// The link target is resolved relative to the directory containing the link.
			// Disallow absolute targets.
			if filepath.IsAbs(header.Linkname) {
				return fmt.Errorf("invalid symlink (%q -> %q) has absolute target",
					header.Name, header.Linkname)
			}

			linkDir := filepath.Dir(path)
			linkTarget := filepath.Join(linkDir, header.Linkname)

			// We must resolve the link target to an absolute path, cleaning it up
			// to prevent any ../ shenanigans.
			linkTarget, err = filepath.Abs(linkTarget)
			if err != nil {
				return fmt.Errorf("invalid symlink %q: %s", header.Name, err)
			}
			linkTarget = filepath.Clean(linkTarget)

			// The resolved link target must be within the destination directory.
			if !strings.HasPrefix(linkTarget, dst+string(os.PathSeparator)) && linkTarget != dst {
				return fmt.Errorf("invalid symlink (%q -> %q) has external target",
					header.Name, header.Linkname)
			}

			// Create the symlink.
			if err := os.Symlink(header.Linkname, path); err != nil {
				return fmt.Errorf("Failed creating symlink (%q -> %q): %v",
					header.Name, header.Linkname, err)
			}

			// Record that we created a symlink
			symlinks[path] = struct{}{}

		case tar.TypeReg, tar.TypeRegA:
			// This is a regular file. We can create it.
			fh, err := os.Create(path)
			if err != nil {
				// This mimics tar's behavior wrt the tar file containing duplicate files
				// and it allowing later ones to clobber earlier ones even if the file
				// has perms that don't allow overwriting.
				if os.IsPermission(err) {
					os.Chmod(path, 0600)
					fh, err = os.Create(path)
				}
				if err != nil {
					return fmt.Errorf("Failed creating file %q: %v", path, err)
				}
			}

			// Copy the contents.
			_, err = io.Copy(fh, untar)
			fh.Close()
			if err != nil {
				return fmt.Errorf("Failed to copy slug file %q: %v", path, err)
			}

			// Restore the file mode. We have to do this after writing the file,
			// since it is possible we have a read-only mode.
			mode := header.FileInfo().Mode()
			if err := os.Chmod(path, mode); err != nil {
				return fmt.Errorf("Failed setting permissions on %q: %v", path, err)
			}

		default:
			return fmt.Errorf("Failed creating %q: unsupported type %c", path,
				header.Typeflag)
		}
	}

	return nil
}

