func isLoopbackURI(requested *url.URL, registeredURI string) bool {
	registered, err := url.Parse(registeredURI)
	if err != nil {
		return false
	}

	// Is the registered URL a loopback address?
	if registered.Scheme != "http" || !isLoopbackAddress(registered.Hostname()) {
		return false
	}

	// Does the requested URL have the same scheme?
	// Does the requested URL have a hostname that is a loopback address?
	if requested.Scheme != "http" || !isLoopbackAddress(requested.Hostname()) {
