exports.killByPort = function (port) {
  var numericPort = parseInt(port, 10);
  if (isNaN(numericPort)) {
    return;
  }

  var processIdBuffer = null;
  try {
    // Use execFileSync to prevent command injection by avoiding the shell.
    processIdBuffer = execFileSync('lsof', ['-t', '-i:' + numericPort]);
  } catch (e) {
    // lsof throws an error if no process is found, so we can ignore it.
  }

  if (processIdBuffer !== null) { // if exists kill
    var pids = processIdBuffer.toString().trim().split('\n');
    for (var i = 0; i < pids.length; i++) {
      var pid = pids[i];
      if (pid) {
        try {
          // Use the safer, built-in process.kill() instead of executing a 'kill' command.
          process.kill(pid);
        } catch (e) {
          // Ignore errors, the process might have already been killed.
        }
      }
    }
  }
}

