  var toEvaluate = expression.replace(new RegExp(unit, "gi"), "")
  var result

  try {
    result = mexp.eval(toEvaluate)
  }
  catch (e) {
    return functionIdentifier + "(" + expression + ")"
  }

  // Transform back to a percentage result:
  if (unit === "%") {
