func (r *MySQL) getSQL(str string) (string, error) {
	if len(strings.TrimSpace(str)) == 0 {
		return "", fmt.Errorf("Empty SQL data")
	}
	fields := strings.Split(str, ":")
	if len(fields) != 5 {
		return "", fmt.Errorf("Invalid SQL data - [%s]. (syntax: database:table:field:key:value)", str)
	}
	db := fields[0]
	table := fields[1]
	field := fields[2]
	key := fields[3]
	value := fields[4]
	//check value is int or not
	if _, err := strconv.Atoi(value); err != nil {
		return "", fmt.Errorf("Invalid SQL data - [%s], the value must be int", str)
	}

	// quoteIdentifier sanitizes a string for use as a MySQL identifier by
	// wrapping it in backticks and escaping any backticks within the string.
	quoteIdentifier := func(s string) string {
		return "`" + strings.ReplaceAll(s, "`", "``") + "`"
	}

	sql := fmt.Sprintf("SELECT %s FROM %s.%s WHERE %s = %s",
		quoteIdentifier(field),
		quoteIdentifier(db),
		quoteIdentifier(table),
		quoteIdentifier(key),
		value)

	return sql, nil
}

