func UntarToDirectory(reader io.Reader, dst string) error {
	// The destination directory should be cleaned and absolute for security reasons.
	absDst, err := filepath.Abs(dst)
	if err != nil {
		return fmt.Errorf("unable to get absolute path for destination %q: %w", dst, err)
	}

	visitor := func(entry TarFileEntry) error {
		// Validate that the file path is within the destination directory.
		target := filepath.Join(absDst, entry.Header.Name)
		if !strings.HasPrefix(target, absDst) {
			return fmt.Errorf("tar entry %q is trying to escape the destination directory %q", entry.Header.Name, absDst)
		}

		switch entry.Header.Typeflag {
		case tar.TypeDir:
			if _, err := os.Stat(target); err != nil {
				if err := os.MkdirAll(target, 0755); err != nil {
					return err
				}
			}

		case tar.TypeReg:
			f, err := os.OpenFile(target, os.O_CREATE|os.O_RDWR, os.FileMode(entry.Header.Mode))
			if err != nil {
				return err
			}

			// limit the reader on each file read to prevent decompression bomb attacks
			numBytes, err := io.Copy(f, io.LimitReader(entry.Reader, perFileReadLimit))
