patch:
def _extract_packages_archive(work_dir):
    package_file = os.path.join(work_dir, "packages.tar")
    if not os.path.exists(package_file):
        return

    curdir = os.path.abspath(os.curdir)

    abs_work_dir = os.path.abspath(work_dir)
    os.chdir(work_dir)
    tar = tarfile.open(package_file)
    for tarinfo in tar:
        if not os.path.abspath(tarinfo.name).startswith(abs_work_dir):
            raise ValueError(
                "Attempted path traversal in tar file: {!r}".format(tarinfo.name)
            )
        tar.extract(tarinfo)
    tar.close()
    if '' not in sys.path:
        sys.path.insert(0, '')

    os.chdir(curdir)

