func (hf *Hoverfly) readResponseBodyFile(filePath string) (string, error) {
	if filepath.IsAbs(filePath) {
		return "", fmt.Errorf("bodyFile contains absolute path (%s). only relative is supported", filePath)
	}

	fullPath := filepath.Join(hf.Cfg.ResponsesBodyFilesPath, filePath)

	// To prevent path traversal, we must ensure the resolved path is still within the base directory.
	// By creating a safe base path with a trailing separator, we can robustly check
	// if the full path has the safe base path as a prefix.
	safeBasePath := filepath.Join(hf.Cfg.ResponsesBodyFilesPath, "/")
	if !strings.HasPrefix(fullPath, safeBasePath) {
		return "", fmt.Errorf("invalid bodyFile path, file is outside of allowed directory: %s", filePath)
	}

	fileContents, err := ioutil.ReadFile(fullPath)
	if err != nil {
		return "", err
	}

	return string(fileContents[:]), nil
}

