func (dag *DAG) EnsureService(meta types.NamespacedName, port intstr.IntOrString, cache *KubernetesCache) (*Service, error) {
	svc, svcPort, err := cache.LookupService(meta, port)
	if err != nil {
		return nil, err
	}

	if svc.Spec.Type == corev1.ServiceTypeExternalName {
		// According to CVE-2021-28682, we must not allow ExternalName
		// services to point to localhost.
		if svc.Spec.ExternalName == "localhost" || svc.Spec.ExternalName == "127.0.0.1" {
