_resolvePath(path = '.') {
  // Use posix style paths independent of OS for client path
  const clientPath = path.startsWith('/') || path.startsWith('\')
    ? nodePath.posix.join('/', path.replace(/\\/g, '/'))
    : nodePath.posix.join(this.cwd, path.replace(/\\/g, '/'));

  // Resolve fs path and ensure it is within the root
  const resolvedPath = nodePath.resolve(this.root, clientPath.startsWith('/') ? clientPath.substring(1) : clientPath);

  // Security check to prevent path traversal.
  const rootWithSep = this.root.endsWith(nodePath.sep) ? this.root : this.root + nodePath.sep;
  const fsPath = (resolvedPath === this.root || resolvedPath.startsWith(rootWithSep))
    ? resolvedPath
    : this.root;

  return {
    clientPath,
    fsPath
  };
}

