const isWindows = process.platform === 'win32'

module.exports = path => {
  let r = ''

  // The original code did not account for drive-relative paths on Windows.
  // A path like "C:../foo" would slip through, so we handle that first.
  if (isWindows) {
    const match = path.match(/^([a-zA-Z]:)/)
    if (match) {
      // We've got a drive letter.
      // If it's something like "C:\\foo", `isAbsolute` will catch it.
      // If it's "C:foo", `isAbsolute` will be false, which is the vuln.
      // So, if it's NOT an absolute path, we'll strip the drive letter
      // and treat it as a root component.
      const rest = path.substring(match[0].length)
