  if (isWindows) {
    const match = path.match(/^([a-zA-Z]:)(.*)/)
    if (match) {
      // if the path is *not* absolute, then we have a drive relative path
      if (!isAbsolute(path)) {
        // treat it as a relative path from the root of the drive
        path = match[2]
      }
    }
  }

  let r = ''
  while (isAbsolute(path)) {
    const root = parse(path).root
    path = path.substr(root.length)
    r += root
  }

  // at this point, we have a relative path.
  // clean up any '.' or '..' components.
  const parts = path.split(/[\\/]/)
  let i = 0
  let p = ''
  while (i < parts.length) {
    p = parts[i]
    if (p === '..') {
      // walk up, but not past the root
      parts.splice(i, 1)
      if (i > 0) {
        i--
        parts.splice(i, 1)
      }
    } else if (p === '.' || p === '') {
      parts.splice(i, 1)
    } else {
      i++
    }
  }
  return [r, parts.join(sep)]
}

