func (k *Keeper) DeleteAccount(ctx sdk.Context, addr common.Address) error {
	cosmosAddr := sdk.AccAddress(addr.Bytes())
	acct := k.accountKeeper.GetAccount(ctx, cosmosAddr)
	if acct == nil {
		return nil
	}

	// NOTE: only Ethereum accounts (contracts) can be selfdestructed
	ethAcct, ok := acct.(ethermint.EthAccountI)
	if !ok {
		return sdkerrors.Wrapf(types.ErrInvalidAccount, "type %T, address %s", acct, addr)
	}

	// clear balance
	if err := k.SetBalance(ctx, addr, new(big.Int)); err != nil {
		return err
	}

	// decrease reference count of the original code hash, and delete the code if
	// the reference count is down to zero.
	codeHash := ethAcct.GetCodeHash()
	codeHashBz := codeHash.Bytes()
	if !bytes.Equal(codeHashBz, types.EmptyCodeHash) {
		store := ctx.KVStore(k.storeKey)
		refCountKey := types.CodeRefCountKey(codeHash)
		if !store.Has(refCountKey) {
			k.Logger(ctx).Error("code reference count not found", "code-hash", codeHash.Hex())
		} else {
			bz := store.Get(refCountKey)
			count := sdk.BigEndianToUint64(bz)

			if count <= 1 {
				// delete code
				k.SetCode(ctx, codeHashBz, nil)
				// delete code reference count
				store.Delete(refCountKey)
			} else {
				bz = sdk.Uint64ToBigEndian(count - 1)
				store.Set(refCountKey, bz)
			}
		}
	}

	// clear storage
	k.ForEachStorage(ctx, addr, func(key, _ common.Hash) bool {
		k.SetState(ctx, addr, key, nil)
		return true
	})

	// remove auth account
	k.accountKeeper.RemoveAccount(ctx, acct)

	k.Logger(ctx).Debug(
		"account suicided",
		"ethereum-address", addr.Hex(),
		"cosmos-address", cosmosAddr.String(),
	)

