func (p *GitLabProvider) addGroupsToSession(ctx context.Context, s *sessions.SessionState) error {
	if len(p.Groups) == 0 {
		return nil
	}

	groupsEndpoint := p.GroupURL.ResolveReference(&url.URL{Path: "/api/v4/groups"})

	type gitlabGroup struct {
		FullPath string `json:"full_path"`
	}

	page := "1"
	for page != "" {
		req, err := http.NewRequestWithContext(ctx, "GET", groupsEndpoint.String(), nil)
		if err != nil {
			return fmt.Errorf("failed to create groups request: %w", err)
		}

		params := req.URL.Query()
		params.Set("per_page", "100")
		params.Set("page", page)
		req.URL.RawQuery = params.Encode()

		req.Header.Set("Accept", "application/json")
		req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", s.AccessToken))

		resp, err := p.Client.Do(req)
		if err != nil {
			return fmt.Errorf("failed to get groups: %w", err)
		}

		body, err := ioutil.ReadAll(resp.Body)
		if err != nil {
			resp.Body.Close()
			return fmt.Errorf("failed to read groups response: %w", err)
		}
		resp.Body.Close()

