+		}
+
+		for _, group := range groups {
+			s.Groups = append(s.Groups, fmt.Sprintf("group:%s", group.FullPath))
+		}
+
+		page = result.Headers().Get("X-Next-Page")
+	}
+
+	return nil
 }

