		return nil, nil
	}

	return tk, nil
}

patch:
func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {
	tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
	if err != nil {
		if err == storage.ErrNotFound {
			// if the tuple is not in storage, check for it in the contextual tuples
			if tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk); ok {
				// validate that the contextual tuple's relation is defined in the model
				if typeInfo, ok := rc.model.GetTypeInfo(tk.GetObjectType()); ok {
					if _, ok := typeInfo.Relations[tk.GetRelation()]; ok {
						return tk, nil
					}
				}
			}
		}

		return nil, err
	}

	return tuple.GetKey(), nil
}

