  // A Set object means a directory reservation
  // A fn is a direct reservation on that path
  const queues = new Map()

  // fn => {paths:[path,...], dirs:[path, ...]}
  const reservations = new Map()

  const platform = process.env.FAKE_PLATFORM || process.platform
  const win32 = platform === 'win32'

  // return a set of parent dirs for a given path
  const getDirs = path => {
    const dirs = new Set()
    path.split('/').slice(0, -1).reduce((parts, part) => {
      // on win32, C:/ is a dir, but C: is not.
      // on unix, / is a dir, but '' is not.
      const p = [...parts, part].join('/') || (win32 ? '' : '/')
      if (p !== '' || !win32) {
        dirs.add(p)
      }
      return [...parts, part]
    }, [])
    return [...dirs]
  }

