                if user_id in tempbans:
                    tempbans.remove(user_id)
                    upgrades.append(str(user_id))
                    log.info(
                        f"{author.name}({author.id}) upgraded the tempban for {user_id} to a permaban."
                    )
            try:
                await guild.ban(user_obj, reason=audit_reason, delete_message_days=days)
                if user_id not in upgrades:
                    log.info(f"{author.name}({author.id}) hackbanned {user_id}")
            except discord.NotFound:
                errors[user_id] = _("User with ID {user_id} not found.").format(user_id=user_id)
                continue
            except discord.Forbidden:
                errors[user_id] = _(
                    "Could not ban user with ID {user_id}: Missing permissions."
                ).format(user_id=user_id)
                continue
            except discord.HTTPException as e:
                errors[user_id] = _("Failed to ban user with ID {user_id}: {reason}.").format(
                    user_id=user_id, reason=e
                )
                continue
            else:
                banned.append(user_id)
                await modlog.create_case(
                    self.bot,
                    guild,
                    ctx.message.created_at.replace(tzinfo=timezone.utc),
                    "hackban",
                    user_id,
                    author,
                    reason,
                )

        await show_results()

