func RequireSignedJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		tok, err := jwt.ParseSigned(rawjwt)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		var claims jwt.Claims
		if err := tok.Claims(key, &claims); err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		// internal JWTs are issued by the databroker and are for the databroker
		const issuer = "pomerium-databroker"
		if err := claims.Validate(jwt.Expected{
			Issuer:   issuer,
			Audience: jwt.Audience{issuer},
			Time:     time.Now(),
		}); err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT claims: %v", err)
		}
	}
	return nil
}

