		if err != nil {
			log.Warnw("Could not get machine-id. JWT tokens will be invalidated on every restart.", "error", err)
			id = uuid.NewString()
		}

		// Use the SHA-256 hash of the ID as the secret for JWT
		h := sha256.New()
		h.Write([]byte(id))
		Secret = h.Sum(nil)
		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
}

