func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)

		encrypter, err := encrypt.NewEncrypter(conf.Server.DataFolder)
		if err != nil {
			log.Fatal("Could not initialize JWT secret encryption. Please check DataFolder configuration and permissions.", "error", err)
		}

		secret, err := ds.Property(context.TODO()).Get(consts.JWTSecretKey)

		// Case 1: Secret exists but is in plaintext (migration from old version).
		// We encrypt it and save it back.
		if err == nil && secret != "" && !encrypter.IsEncrypted(secret) {
			log.Info("Found plaintext JWT secret, encrypting it now. All user sessions will be invalidated.")
			secret, err = encrypter.Encrypt(secret)
			if err == nil {
				err = ds.Property(context.TODO()).Save(consts.JWTSecretKey, secret)
			}
			if err != nil {
				log.Fatal("Failed to encrypt and save the JWT secret. Please report this issue.", "error", err)
			}
		}

		// Case 2: Secret does not exist (new installation) or there was an error getting it.
		// We generate a new one, encrypt it, and save it.
		if err != nil || secret == "" {
			if err != nil && !errors.Is(err, model.ErrNotFound) {
				log.Warn("Could not retrieve JWT Secret from DB, a new one will be generated.", "error", err)
			}
			log.Info("Generating new JWT secret.")
			plainSecret := uuid.NewString()
			secret, err = encrypter.Encrypt(plainSecret)
			if err == nil {
				err = ds.Property(context.TODO()).Save(consts.JWTSecretKey, secret)
			}
			if err != nil {
				log.Fatal("Failed to generate and save a new JWT secret.", "error", err)
			}
		}

		// At this point, `secret` holds the encrypted JWT secret from the DB. We decrypt it.
		plainSecret, err := encrypter.Decrypt(secret)
		if err != nil {
			log.Fatal("Could not decrypt JWT Secret. Your DataFolder may have changed. If so, you need to restore it from a backup, or delete navidrome.db to start fresh (losing all user data).", "error", err)
		}

		Secret = []byte(plainSecret)
		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
}

