func (fs *Filesystem) Delete(p string) error {
	// Safely resolve the parent directory of the path provided. If the parent
	// directory is not within the server's data directory, we can assume that
	// this is a malicious request.
	//
	// This allows us to still delete a symlink that is pointing to a location
	// on the disk that is outside the data directory.
	dir := filepath.Dir(p)
	absDir := fs.unsafeFilePath(dir)

	resolvedDir, err := filepath.EvalSymlinks(absDir)
	if err != nil {
		// If we get an error, just fall back to the absolute directory path. If
		// this is also not in the data directory there isn't anything we can do.
		//
		// This handles cases where the link is broken, or the path doesn't exist,
		// but we still want to try and delete it.
		if !fs.unsafeIsInDataDirectory(absDir) {
			return NewBadPathResolution(dir, absDir)
		}
		resolvedDir = absDir
	}

	// And now, if the resolved directory is not within the data directory, return
	// a bad path resolution error.
	if !fs.unsafeIsInDataDirectory(resolvedDir) {
		return NewBadPathResolution(dir, resolvedDir)
	}

	// Join the resolved parent directory with the un-resolved base name. This
	// is the path that we will end up deleting.
	resolved := filepath.Join(resolvedDir, filepath.Base(p))

	// Just in case, re-verify that the final path is within the data directory.
	// This can happen if the base path is `..` for example.
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	st, err := os.Lstat(resolved)
	if err != nil {
		// If the file doesn't exist, we don't need to do anything. We can just return
		// nil and carry on. If we returned the os.IsNotExist error, things would break
		// upstream that are just blindly calling a file deletion and not checking if
		// the file exists beforehand.
		if os.IsNotExist(err) {
			return nil
		}
		fs.error(err).Warn("error while attempting to stat file before deletion")
		return err
	}

	// If the file is a symlink we want to just remove the link itself and not the
	// underlying file. In that case, just call os.Remove and that's it.
	if st.Mode()&os.ModeSymlink == os.ModeSymlink {
		fs.addDisk(-st.Size())
		return os.Remove(resolved)
	}

	// If the file isn't a directory just go ahead and remove it, adjusting the
	// disk space along the way.
	if !st.IsDir() {
		fs.addDisk(-st.Size())
		return os.Remove(resolved)
	}

	// Otherwise, we're deleting a directory. We need to get the size of the
	// directory and then remove it all.
	size, err := fs.DirectorySize(resolved)
	if err != nil {
		fs.error(err).Warn("failed to get directory size before deletion")
		// Continue with the deletion, just don't update the disk space.
	} else {
		fs.addDisk(-size)
	}

	return os.RemoveAll(resolved)
}

