from django.contrib.auth import get_user_model
from django.core.exceptions import PermissionDenied

from wagtail.admin.views.bulk_action import BulkAction
from wagtail.users.permission_policies import users_permission_policy


class UserBulkAction(BulkAction):
    models = [get_user_model()]

    def check_perm(self, obj):
        # The `obj` in this case is a user that is trying to perform the action.
        # We need to check if they have permission to perform the action on other
        # users.
        if not users_permission_policy.user_has_any_permission(
            obj, self.get_permissions()
        ):
            raise PermissionDenied
        return True

    def get_permissions(self):
        # This is a bit of a hack, but we need to check for permissions on the
        # user model, but we don't know which action is being performed.
        # The `user_has_any_permission` method will check for any of the
        # permissions, so we can just return all of them.
        return ["add", "change", "delete"]

    def get_execution_context(self):
        return {
            **super().get_execution_context(),
            "permission_policy": users_permission_policy,
        }

