from wagtail.admin.views.bulk_action import BulkAction


class UserBulkAction(BulkAction):
    models = [get_user_model()]
    permission_policy = None

    @classmethod
    def _load_permission_policy(cls):
        if cls.permission_policy is None:
            from wagtail.users.permissions import (
                permission_policy as users_permission_policy,
            )

            cls.permission_policy = users_permission_policy
        return cls.permission_policy

    def check_perm(self, user):
        """
        Check that the user has permission to perform the action.
        """
        policy = self._load_permission_policy()
        if not policy.user_has_any_permission(user, self.get_permissions()):
            raise PermissionDenied
        return True

    def get_permissions(self):
        """
        Get the permissions required to perform the action.
        This is a bit of a hack, but we need to check for permissions on the
        user model, but we don't know which action is being performed.
        The `user_has_any_permission` method will check for any of the
        permissions, so we can just return all of them.
        """
        return ["add", "change", "delete"]

    def get_execution_context(self):
        return {
            **super().get_execution_context(),
            "permission_policy": self._load_permission_policy(),
        }

