module.execute = function(arrParams) {
    return new Promise(function(resolve, reject) {
        var execFile = require('child_process').execFile;
        var jarPath = path.join(__dirname, 'jar', 'key-sender.jar');

        // To prevent command injection, we build an array of arguments and use execFile,
        // which does not spawn a shell.
        var jarArgsString = arrParams.join(' ') + module.getCommandLineOptions();
        var args = ['-jar', jarPath].concat(
            // We split the combined arguments string by whitespace to mimic the shell's
            // word splitting from the original code, and filter out any empty strings.
            jarArgsString.trim().split(/\s+/).filter(function(arg) { return arg.length > 0; })
        );

        return execFile('java', args, {}, function(error, stdout, stderr) {
            if (error == null) {
                resolve(stdout, stderr);
            } else {
                reject(error, stdout, stderr);
            }
        });
    });
};

