function template(literal, data) {
  return literal.replace(/\$\{([^{}]+)\}/g, function (match, key) {
    var path = key.trim().split('.');
    var value = path.reduce(function (acc, part) {
      return acc ? acc[part] : undefined;
    }, data);

    return (value !== undefined && value !== null) ? value : '';
  });
}

