    // Validate output to prevent any shell-like characters.
    // This regex checks for anything that is NOT a word character, a hyphen, or a dot.
    const invalidCharRegex = /[^\w.-]/;
    if (typeof output !== 'string' || output.trim() === '' || invalidCharRegex.test(output)) {
      return reject(new Error("Invalid characters in output filename."));
    }

    if (fs.existsSync(input)) {
      const outputFilename = `${output}.mp4`;
      execFile("ffmpeg", [
          "-hide_banner",
          "-loglevel",
          "quiet",
          "-ss",
          String(start),
          "-i",
