def deny_uploads_containing_script_tag(uploaded_file):
    # This validator checks for a forbidden string across chunk boundaries
    # to prevent bypass attacks, reading the file in a streaming fashion.
    # It also checks for the presence of the string regardless of whitespace
    # between its characters. See CVE-2023-33977
    forbidden = b"<script"
    forbidden_pos = 0

    for chunk in uploaded_file.chunks():
        for char_code in chunk:
            char = bytes([char_code])
            if char.isspace():
                continue

            # use .lower() to perform case-insensitive matching
            if char.lower() == bytes([forbidden[forbidden_pos]]):
                forbidden_pos += 1
            # reset if the first char doesn't match
            elif char.lower() == bytes([forbidden[0]]):
                forbidden_pos = 1
            # reset if we have a non-matching character
            else:
                forbidden_pos = 0

            if forbidden_pos == len(forbidden):
                raise ValidationError(_("File contains forbidden <script> tag"))

    # Do not reset file cursor b/c we may be chaining validators

