var main = function(req, res) {
        var reqUrl = req.url; 
        //记录请求信息
        logger.http(req, res);

        //使用url解析模块获取url中的路径名 
        var pathName = url.parse(reqUrl).pathname;

        try {
            pathName = decodeURIComponent(pathName);
        } catch (e) {
            res.writeHead(400, {"Content-Type": "text/html"});
            res.end('<h1>400 Bad Request</h1>');
            return;
        }

        //补全文件路径
        if (path.extname(pathName) == "") {

            if(!/\/$/.test(pathName)){
                pathName += '/';
            }

            pathName += argvs.getDefault();
        }

        const root = path.resolve(argvs.getPath());
        // By prepending './' to pathName, we ensure path.join treats it as relative
        // to the root, preventing escape from the webroot. Normalization resolves '..' etc.
        var filePath = path.normalize(path.join(root, '.' + pathName));

        // Security check: ensure the final path is within the root directory.
        if (filePath.indexOf(root) !== 0) {
            res.writeHead(404, {"Content-Type": "text/html"});
            res.end('<h1>404 Not Found</h1>');
            return;
        }

        //判断文件是否存在 
        fs.exists(filePath, function(exists) {
            try{
                if (exists) {
                    //在返回头中写入内容类型 
                    res.writeHead(200, {
                        "Content-Type": mime.lookup(filePath)
                    });

                    //创建只读流用于返回 
                    var stream = fs.createReadStream(filePath, {
                        flags: "r",
                        encoding: null
                    });

                    //指定如果流读取错误,返回500错误 
                    stream.on("error", function() {
                        res.writeHead(500);
                        res.end('<h1>500 the file [path=' + filePath +'] Read Error!</h1>');
                    });
                    //连接文件流和http返回流的管道,用于返回实际Web内容 
                    stream.pipe(res);
                } else {
                    //返回404错误 
                    res.writeHead(404, {
                        "Content-Type": "text/html"
                    });
                    res.end('<h1>404 Not Found file [path=' + filePath + ']</h1>');
                }
            }catch(e){
                logger.error('read file from [' + filePath + '] error!');
            }
        });
    }

